export type ParsedExecuteMultiRouteInstruction<
  TProgram extends string = typeof CLEARING_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    actor: TAccountMetas[0];
    venue: TAccountMetas[1];
    safety: TAccountMetas[2];
    market: TAccountMetas[3];
    otherMarket?: TAccountMetas[4] | undefined;
    ledger: TAccountMetas[5];
    otherLedger?: TAccountMetas[6] | undefined;
    trader: TAccountMetas[7];
    registry: TAccountMetas[8];
    zeroCapital: TAccountMetas[9];
    zeroRegistration: TAccountMetas[10];
    /** CHECK: the sealed registration binds the executable and its approved code. */
    zeroProgram: TAccountMetas[11];
    zeroProgramData: TAccountMetas[12];
    /** CHECK: clearing authenticates the maker-owned curve, price and current authority. */
    zeroConfig: TAccountMetas[13];
    /** CHECK: a fixed read-only maker PDA bound to the curve. */
    zeroPrice: TAccountMetas[14];
    oneCapital: TAccountMetas[15];
    oneRegistration: TAccountMetas[16];
    /** CHECK: the sealed registration binds the executable and its approved code. */
    oneProgram: TAccountMetas[17];
    oneProgramData: TAccountMetas[18];
    /** CHECK: clearing authenticates the maker-owned curve, price and current authority. */
    oneConfig: TAccountMetas[19];
    /** CHECK: a fixed read-only maker PDA bound to the curve. */
    onePrice: TAccountMetas[20];
    twoCapital: TAccountMetas[21];
    twoRegistration: TAccountMetas[22];
    /** CHECK: the sealed registration binds the executable and its approved code. */
    twoProgram: TAccountMetas[23];
    twoProgramData: TAccountMetas[24];
    /** CHECK: clearing authenticates the maker-owned curve, price and current authority. */
    twoConfig: TAccountMetas[25];
    /** CHECK: a fixed read-only maker PDA bound to the curve. */
    twoPrice: TAccountMetas[26];
    /** CHECK: Only the event authority can invoke self-CPI */
    eventAuthority: TAccountMetas[27];
    /** CHECK: Kept for v1-compatible account ordering and IDL shape */
    program: TAccountMetas[28];
  };
  data: ExecuteMultiRouteInstructionData;
};

export function parseExecuteMultiRouteInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedExecuteMultiRouteInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 29) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 29,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === CLEARING_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      actor: getNextAccount(),
      venue: getNextAccount(),
      safety: getNextAccount(),
      market: getNextAccount(),
      otherMarket: getNextOptionalAccount(),
      ledger: getNextAccount(),
      otherLedger: getNextOptionalAccount(),
      trader: getNextAccount(),
      registry: getNextAccount(),
      zeroCapital: getNextAccount(),
      zeroRegistration: getNextAccount(),
      zeroProgram: getNextAccount(),
      zeroProgramData: getNextAccount(),
      zeroConfig: getNextAccount(),
      zeroPrice: getNextAccount(),
      oneCapital: getNextAccount(),
      oneRegistration: getNextAccount(),
      oneProgram: getNextAccount(),
      oneProgramData: getNextAccount(),
      oneConfig: getNextAccount(),
      onePrice: getNextAccount(),
      twoCapital: getNextAccount(),
      twoRegistration: getNextAccount(),
      twoProgram: getNextAccount(),
      twoProgramData: getNextAccount(),
      twoConfig: getNextAccount(),
      twoPrice: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getExecuteMultiRouteInstructionDataDecoder().decode(instruction.data),
  };
}
